const getDialogDescription = () => {
  if (missingName && isExternal) {
    return <FormattedMessage {...msgs.deleteApp} />;
  }
  if (missingName) {
    return <FormattedMessage {...msgs.deleteLocalApp} />;
  }
  if (isExternal) {
    return (
      <FormattedMessage
        {...msgs.deleteNamedApp}
        values={{
          name: <strong>{getStringOrPlaceholder(name)}</strong>,
        }}
      />
    );
  }
  return (
    <FormattedMessage
      {...msgs.deleteLocalNamedApp}
      values={{
        name: <strong>{getStringOrPlaceholder(name)}</strong>,
      }}
    />
  );
};

return (
  <ActionDialog
    confirmButtonState={confirmButtonState}
    open={open}
    onClose={onClose}
    onConfirm={onConfirm}
    title={intl.formatMessage(msgs.deleteAppTitle)}
    variant="delete"
  >
    <DialogContentText data-test-id="dialog-content">
      {getDialogDescription()}{" "}
      <FormattedMessage {...msgs.deleteAppQuestion} />
    </DialogContentText>
  </ActionDialog>
);

